function getImportance(employees, id) {
  const byId = new Map(employees.map((e) => [e.id, e]));
  const boss = byId.get(id);
  let total = boss.importance;
  for (const childId of boss.subordinates) {
    total += byId.get(childId).importance;
  }
  return total;
}

