      gold++;
    }
    for (const [rowChange, columnChange] of [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ]) {
      const nextRow = row + rowChange;
      const nextColumn = column + columnChange;
      const key = `${nextRow},${nextColumn}`;
      if (
        isInBounds(grid, nextRow, nextColumn) &&
