function hasPathSum(root, targetSum) {
  function search(node, sum) {
    if (!node) {
      return false;
    }
    const next = sum + node.val;
    if (next === targetSum) {
      return true;
    }
    return search(node.left, next) || search(node.right, next);
  }
  return search(root, 0);
}

